<script lang="ts">import{formatLinearGradient}from'@fex-design/core/gradient/gradient';import{gradientPickerTrackClassName}from'@fex-design/styles/color-picker';import{cn}from'@fex/utils';import type{Snippet}from'svelte';import type{HTMLAttributes}from'svelte/elements';import{useGradientPicker}from'./context';interface Props extends Omit<HTMLAttributes<HTMLDivElement>,'children'>{children?:Snippet}let{class:className,children,...rest}:Props=$props();const picker=useGradientPicker(),snapshot=$derived(picker.snapshot()),background=$derived(formatLinearGradient(snapshot.value))</script><div {...rest} class={cn(gradientPickerTrackClassName,className)} style:--gradient-picker-background={background} onpointerdown={(event)=>{if(event.target!==event.currentTarget||snapshot.disabled)return;const rect=event.currentTarget.getBoundingClientRect();picker.controller.addStop((event.clientX-rect.left)/rect.width)}}>{@render children?.()}</div>
